function downloadExcelTemplate(filename,sheetName,headers,rows){const ws=XLSX.utils.aoa_to_sheet([headers,...rows]);const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,sheetName);XLSX.writeFile(wb,filename)}
function invoiceDocumentHtml({settings={},reference='',saleReference='',status='PAID',customer={},date='',items=[],total=0,totalLabel='Total'}){const esc=invoiceEscape;const contacts=[settings.address,settings.location,settings.contact_phone?`Phone: ${settings.contact_phone}`:'',settings.contact_email?`Email: ${settings.contact_email}`:'',].filter(Boolean).map(x=>`<div>${esc(x)}</div>`).join('');const rows=items.map(i=>{const raw=i.unit_price_snapshot??i.box_price_snapshot??i.unit_price;return `<tr><td>${esc(i.product_name||i.product_name_snapshot||'Product')}</td><td>${esc(i.product_code||i.product_code_snapshot||'')}</td><td>${esc(i.quantity_label||i.quantity||i.confirmed_boxes||i.quantity_units||'')}</td><td class="money">${raw==null?'Pending branch review':esc(money(raw))}</td><td class="money">${i.line_total==null?'Pending':esc(money(i.line_total))}</td></tr>`}).join('');return `<!doctype html><html><head><meta charset="utf-8"><title>${esc(settings.pharmacy_name||'Pharmacy')} - Invoice ${esc(reference)}</title><style>@page{size:A4;margin:14mm}*{box-sizing:border-box}body{font:12px Arial,sans-serif;color:#18332e;margin:0}header{display:flex;align-items:center;gap:18px;padding:0 0 16px;border-bottom:2px solid #087967}.logo{width:84px;height:84px;object-fit:contain}h1{font-size:23px;color:#087967;margin:0 0 8px}.contact{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:4px 16px;color:#52635f}.invoice-title{display:flex;justify-content:space-between;align-items:flex-start;margin:22px 0 14px}.invoice-title h2{margin:0 0 5px;font-size:20px}.status{display:inline-block;padding:7px 11px;border:1px solid #9dcabc;border-radius:20px;background:#edf7f2;color:#176957;font-weight:bold}.meta{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:14px 0 20px}.meta section{border:1px solid #d4e2dc;border-radius:7px;padding:10px}.meta b{display:block;font-size:10px;color:#688078;text-transform:uppercase;margin-bottom:5px}table{width:100%;border-collapse:collapse;border:1px solid #bdcec6}th,td{padding:9px 8px;text-align:left;border:1px solid #d4e2dc}th{background:#eaf5f1;color:#28554a;font-size:10px;text-transform:uppercase}.money{text-align:right;white-space:nowrap}.total{display:flex;justify-content:flex-end;margin-top:16px}.total b{min-width:220px;padding:13px;border:1px solid #96b9ad;background:#f2f8f5;text-align:right;font-size:17px}.thanks{margin-top:28px;color:#60756e;border-top:1px solid #dce8e3;padding-top:12px}@media print{button{display:none}}</style></head><body><header>${settings.logo_url?`<img class="logo" src="${esc(settings.logo_url)}" alt="${esc(settings.pharmacy_name||'Pharmacy')} logo">`:''}<div><h1>${esc(settings.pharmacy_name||'Pharmacy')}</h1><div class="contact">${contacts}</div></div></header><div class="invoice-title"><div><h2>Invoice</h2><div>Reference: <b>${esc(reference)}</b></div></div><span class="status">${esc(status)}</span></div><div class="meta"><section><b>Customer</b>${esc(customer.name||customer.full_name||'Walk-in customer')}<br>${esc(customer.email||'')}<br>${esc(customer.phone||'')}</section><section><b>Sale / order</b>${esc(saleReference||reference)}</section><section><b>Date</b>${esc(date?new Date(date).toLocaleDateString():new Date().toLocaleDateString())}</section></div><table><thead><tr><th>Product</th><th>Code</th><th>Quantity</th><th class="money">Unit price</th><th class="money">Line total</th></tr></thead><tbody>${rows}</tbody></table><div class="total"><b>${esc(totalLabel)}: ${esc(money(total))}</b></div><div class="thanks">Thank you for choosing ${esc(settings.pharmacy_name||'our pharmacy')}.</div></body></html>`}
function printInvoicePdf(invoice){const win=window.open('','_blank');if(!win)return false;win.document.write(invoiceDocumentHtml({settings:invoice.settings,reference:invoice.reference,saleReference:invoice.saleReference,status:invoice.status||'UNPAID DRAFT',customer:invoice.customer||{},date:invoice.date,total:invoice.total,totalLabel:invoice.totalLabel||'Invoice total',items:invoice.items||[]}));win.document.close();win.onload=()=>win.print();return true}
function InvoicePreviewCard({invoice,onDownload}){const s=invoice.settings||{};return <section className="invoice-preview-document"><header>{s.logo_url?<img src={s.logo_url} alt="Pharmacy logo"/>:<span className="invoice-preview-logo"><HeartPulse size={22}/></span>}<div><h3>{s.pharmacy_name||'Pharmacy'}</h3><p>{[s.address,s.location,,s.contact_phone,s.contact_email].filter(Boolean).join(' | ')}</p></div><b className="invoice-preview-status">{invoice.status}</b></header><div className="invoice-preview-meta"><span><small>Invoice</small><b>{invoice.reference}</b></span><span><small>Customer</small><b>{invoice.customer?.name||invoice.customer?.full_name||'Walk-in customer'}</b></span><span><small>Date</small><b>{invoice.date?new Date(invoice.date).toLocaleDateString():'Today'}</b></span></div><div className="table-wrap"><table><thead><tr><th>PRODUCT</th><th>CODE</th><th>QUANTITY</th><th>UNIT PRICE</th><th>LINE TOTAL</th></tr></thead><tbody>{(invoice.items||[]).map((i,n)=><tr key={(i.product_code||i.product_code_snapshot||'item')+n}><td><b>{i.product_name||i.product_name_snapshot}</b></td><td>{i.product_code||i.product_code_snapshot||'N/A'}</td><td>{i.quantity_label||i.quantity||i.confirmed_boxes||i.quantity_units}</td><td>{(i.unit_price_snapshot??i.box_price_snapshot)==null?'Pending branch review':money(i.unit_price_snapshot??i.box_price_snapshot)}</td><td>{i.line_total==null?'Pending':money(i.line_total)}</td></tr>)}</tbody><tfoot><tr><th colSpan="4">{invoice.totalLabel||'Invoice total'}</th><th>{money(invoice.total)}</th></tr></tfoot></table></div><p className="invoice-preview-contact">{[s.contact_phone,s.contact_email,s.address,s.location,].filter(Boolean).join(' | ')}</p><button type="button" className="button button-outline invoice-preview-download" onClick={onDownload||(()=>printInvoicePdf(invoice))}><ArrowDownToLine size={15}/> Print / Save PDF</button></section>}

function SnapBar({message,onDismiss}){useEffect(()=>{if(!message)return;const timer=window.setTimeout(onDismiss,5000);return()=>window.clearTimeout(timer)},[message]);if(!message)return null;const isError=/(failed|unable|error|could not|incorrect|invalid|timed out|not configured|already in use|denied|forbidden|not found|required|must be|insufficient|no .* available)/i.test(message);return <div className={`snapbar ${isError?'snapbar-error':'snapbar-success'}`} role="status" aria-live="polite"><span className="snapbar-mark"><HeartPulse size={17}/></span><span className="snapbar-message">{message}</span><button type="button" className="snapbar-close" aria-label="Dismiss notification" onClick={onDismiss}><X size={16}/></button><span className="snapbar-progress"/></div>}

