function RecordsFilterBar({search,onSearch,placeholder='Search records',status,onStatus,statusOptions=[],from,onFrom,to,onTo}){return <div className="records-filter-bar"><label className="searchbox"><Search size={15}/><input value={search} onChange={e=>onSearch(e.target.value)} placeholder={placeholder}/></label>{statusOptions.length>0&&<select aria-label="Filter by status" value={status} onChange={e=>onStatus(e.target.value)}><option value="">All statuses</option>{statusOptions.map(x=><option key={x.value} value={x.value}>{x.label}</option>)}</select>}{from!==undefined&&to!==undefined&&onFrom&&onTo&&<><label className="date-filter"><span>From</span><input type="date" aria-label="From date" value={from} onChange={e=>onFrom(e.target.value)}/></label><label className="date-filter"><span>To</span><input type="date" aria-label="To date" value={to} onChange={e=>onTo(e.target.value)}/></label></>}</div>}
function dateInRange(value,from,to){if(!value)return !from&&!to;const day=String(value).slice(0,10);return (!from||day>=from)&&(!to||day<=to)}
function readCart(){try{const saved=JSON.parse(localStorage.getItem('pharmacy_cart')||'[]');if(!Array.isArray(saved))return [];const merged=[];for(const item of saved){const existing=merged.find(x=>Number(x.product_id)===Number(item.product_id));if(existing)existing.boxes=Number(existing.boxes||0)+Number(item.boxes||0);else merged.push({...item,boxes:Number(item.boxes||0)})}return merged}catch{return []}}
