function googleMapsEmbedUrl(mapLink,fallbackQuery=''){const raw=String(mapLink||'').trim();if(!raw)return fallbackQuery?`https://www.google.com/maps?q=${encodeURIComponent(fallbackQuery)}&output=embed`:'';if(/google\.[^/]+\/maps\/embed/i.test(raw))return raw;let target='';try{const u=new URL(raw);target=u.searchParams.get('q')||u.searchParams.get('query')||u.searchParams.get('destination')||'';if(!target){const place=u.pathname.match(/\/place\/([^/]+)/i);if(place)target=decodeURIComponent(place[1].replace(/\+/g,' '))}if(!target){const coords=u.href.match(/@(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?)/);if(coords)target=`${coords[1]},${coords[2]}`}if(!target&&/maps\.app\.goo\.gl/i.test(u.hostname))target=fallbackQuery}catch{}target=target||fallbackQuery;return target?`https://www.google.com/maps?q=${encodeURIComponent(target)}&output=embed`:''}
function PublicTeamSection({settings={},branches=[]}){const [staff,setStaff]=useState([]);useEffect(()=>{api.get('/team').then(r=>setStaff(r.data.staff||[])).catch(()=>setStaff([]))},[]);let curated=[];try{const parsed=JSON.parse(settings.team_members||'[]');if(Array.isArray(parsed))curated=parsed.filter(m=>m&&m.name)}catch{}const manualNames=new Set(curated.map(m=>String(m.name).trim().toLowerCase()));const members=[...curated.map(m=>({...m,display_name:m.name,subtitle:m.description||'Pharmacy team'})),...staff.filter(m=>!manualNames.has(String(m.full_name).trim().toLowerCase())).map(m=>({...m,display_name:m.full_name,subtitle:[m.staff_position,m.branch_name].filter(Boolean).join(' | ')||'Pharmacy team'}))];if(!members.length)return null;return <section className="public-section team-section" id="our-team" data-reveal><div className="section-heading"><div><div className="eyebrow">OUR TEAM</div><h2>Meet our pharmacy team</h2><p>Our team is here to support your health and wellbeing.</p></div></div><div className="team-grid">{members.map((member,index)=><article className="team-card" data-reveal key={`${member.id||member.display_name}-${index}`}>{member.image_url?<img src={member.image_url} alt={member.display_name}/>:<span className="public-staff-avatar" aria-hidden="true">{member.display_name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()}</span>}<div><h3>{member.display_name}</h3><p>{member.subtitle}</p></div></article>)}</div></section>}
