function AboutUsPage({settings,branches=[],onNotify}){const [form,setForm]=useState({full_name:'',email:'',branch_id:'',rating:'5',message:''}),[busy,setBusy]=useState(false);async function submit(e){e.preventDefault();setBusy(true);try{await api.post('/feedback',{...form,branch_id:form.branch_id?Number(form.branch_id):null,rating:Number(form.rating)});setForm({full_name:'',email:'',branch_id:'',rating:'5',message:''});onNotify?.('Thank you. Your feedback has been received.')}catch(err){onNotify?.(err.response?.data?.error||'Unable to send feedback')}finally{setBusy(false)}}return <div className="public" style={{"--green":settings.primary_color||"#087967","--wash":settings.accent_color||"#eaf5f1"}}><PublicPageHeader settings={settings} branches={branches}/><main><section className="public-section about-hero"><div className="eyebrow">ABOUT {settings.pharmacy_name||'OUR PHARMACY'}</div><h1>{settings.hero_title||`About ${settings.pharmacy_name||'our pharmacy'}`}</h1><p>{settings.about_text||settings.hero_text||'We serve our community through our pharmacy branches, offering access to medicines and attentive service from our pharmacy team.'}</p></section><section className="public-section about-feedback"><div className="section-heading"><div><div className="eyebrow">YOUR VOICE MATTERS</div><h2>Share feedback</h2><p>Tell us about your experience or send a suggestion to our pharmacy team.</p></div></div><form className="feedback-form" onSubmit={submit}><label>Your name<input required maxLength="160" value={form.full_name} onChange={e=>setForm({...form,full_name:e.target.value})}/></label><label>Email address<input type="email" maxLength="190" value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></label><label>Branch<select value={form.branch_id} onChange={e=>setForm({...form,branch_id:e.target.value})}><option value="">General feedback</option>{branches.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select></label><label>Rating<select value={form.rating} onChange={e=>setForm({...form,rating:e.target.value})}><option value="5">Excellent</option><option value="4">Good</option><option value="3">Fair</option><option value="2">Needs improvement</option><option value="1">Poor</option></select></label><label className="feedback-message">Your feedback<textarea required minLength="5" maxLength="3000" rows="5" value={form.message} onChange={e=>setForm({...form,message:e.target.value})}/></label><button className="button button-primary" disabled={busy}>{busy?<><LoadingSpinner/> Sending...</>:'Send feedback'}</button></form></section></main><PublicTeamSection settings={settings} branches={branches}/><PublicFooter settings={settings} branches={branches}/></div>}
function PublicFooter({settings,branches=[]}){return <><BranchLocationsSection branches={branches}/><footer className="public-footer" id="site-footer"><div className="footer-contact"><div className="public-brand">{settings.logo_url?<img className="configured-logo" src={settings.logo_url} alt=""/>:<span className="brand-mark"><HeartPulse size={17}/></span>}{settings.pharmacy_name}</div><div className="footer-contact-details">{settings.social_whatsapp&&<a href={/^https?:\/\//i.test(settings.social_whatsapp)?settings.social_whatsapp:`https://wa.me/${String(settings.social_whatsapp).replace(/\D/g,'')}`} target="_blank" rel="noreferrer">WhatsApp contact</a>}{settings.social_facebook&&<a href={settings.social_facebook} target="_blank" rel="noreferrer">Facebook</a>}{settings.social_instagram&&<a href={settings.social_instagram} target="_blank" rel="noreferrer">Instagram</a>}</div></div><div className="footer-bottom"><span>&copy; {new Date().getFullYear()} {settings.pharmacy_name}</span><a className="footer-share-link" href={`${api.defaults.baseURL}/share`}>Share pharmacy site</a><a className="footer-developer" href="https://www.kachehub.com" target="_blank" rel="noreferrer">Developed by Kachehub</a><a className="button button-outline footer-staff-link" href="/?staff=1">Admin &amp; staff sign in <ArrowRight size={15}/></a></div></footer></>}
