function GenericTable({columns,rows,loading,empty}){const [query,setQuery]=useState('');const filtered=rows.filter(r=>r.some(cell=>String(cell??'').toLowerCase().includes(query.toLowerCase())));return <div className="panel table-panel"><div className="toolbar"><div><h2>Recent records</h2><p>Latest records from the pharmacy database.</p></div><label className="searchbox"><Search size={16}/><input placeholder="Search records"/></label></div><div className="records-filter-bar"><label className="searchbox"><Search size={15}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search records"/></label></div><div className="table-wrap"><table><thead><tr>{columns.map(c=><th key={c}>{c.toUpperCase()}</th>)}</tr></thead><tbody>{loading?<tr><td colSpan={columns.length} className="table-empty">Loading recordsâ€¦</td></tr>:filtered.length?filtered.map((r,i)=><tr key={i}>{r.map((cell,j)=><td key={j}>{j===2?<span className="status-pill status-good"><i/>{cell}</span>:cell}</td>)}</tr>):<tr><td colSpan={columns.length} className="table-empty">No records match this search.</td></tr>}</tbody></table></div></div>}
