function FinanceReportCharts({report}){const records=report?.records||[],daily=new Map();for(const r of records){const day=r.date||'Unknown';if(!daily.has(day))daily.set(day,{sales:0,expenses:0});const item=daily.get(day);if(r.record_type==='Expense')item.expenses+=Number(r.amount||0);else if(r.status==='paid')item.sales+=Number(r.amount||0)}const points=[...daily.entries()].slice(-14),max=Math.max(1,...points.flatMap(([,v])=>[v.sales,v.expenses]));const statusCounts=['paid','pending','unpaid','rejected'].map(status=>({status,count:records.filter(r=>r.status===status).length}));const maxCount=Math.max(1,...statusCounts.map(x=>x.count));return <div className="finance-report-charts"><div className="finance-chart-card"><div><h3>Daily paid sales and expenses</h3><p>Amount by transaction date, showing up to the latest 14 dates</p></div><div className="finance-chart-legend"><span><i className="legend-sales"/>Paid sales</span><span><i className="legend-expenses"/>Expenses</span></div><svg viewBox="0 0 720 230" role="img" aria-label="Daily paid sales and expenses chart"><line x1="42" y1="180" x2="700" y2="180" stroke="#dce8e3"/>{points.map(([day,value],i)=>{const gap=650/Math.max(points.length,1),x=48+i*gap,w=Math.min(18,gap*.32),salesH=value.sales/max*130,expenseH=value.expenses/max*130;return <g key={day}><rect x={x} y={180-salesH} width={w} height={salesH} rx="4" fill="#087967"><title>{day}: paid sales {money(value.sales)}</title></rect><rect x={x+w+3} y={180-expenseH} width={w} height={expenseH} rx="4" fill="#d39b42"><title>{day}: expenses {money(value.expenses)}</title></rect><text x={x+w} y="202" textAnchor="middle">{day.slice(5)}</text></g>})}</svg><div className="finance-chart-foot"><span>Paid income <b>{money(report?.summary?.paid_amount||0)}</b></span><span>Expenses <b>{money(report?.summary?.expense_amount||0)}</b></span><span>Net income <b>{money(report?.summary?.net_income||0)}</b></span></div></div><div className="finance-chart-card status-chart-card"><div><h3>Transaction status mix</h3><p>Records included in this filtered report</p></div><div className="finance-status-chart">{statusCounts.map(({status,count})=><div className="finance-status-row" key={status}><span>{status}</span><i><em className={'status-'+status} style={{width:`${count?Math.max(5,count/maxCount*100):0}%`}}/></i><b>{count}</b></div>)}</div><div className="finance-chart-foot"><span>Total transactions <b>{report?.summary?.records||0}</b></span><span>Expenses <b>{report?.summary?.expenses_count||0}</b></span></div></div></div>}
